'use strict';
// Versión 2.3: el tutorial visual. Capítulos, tareas, dibujos de la tarjeta y los pasos nuevos o reescritos.
// Como en tutorial.js, se conservan las etiquetas HTML de los textos.
registrarTextos([
  // Capítulos y botones
  ["Primeros pasos", "First steps", "Erste Schritte", "Premiers pas", "Primeiros passos"],
  ["Crear la partida", "Setting up the game", "Spiel einrichten", "Créer la partie", "Criar a partida"],
  ["La carrera", "The career", "Die Karriere", "La carrière", "A carreira"],
  ["Campaña y elecciones", "Campaign and elections", "Wahlkampf und Wahlen", "Campagne et élections", "Campanha e eleições"],
  ["Tu país", "Your country", "Dein Land", "Votre pays", "Seu país"],
  ["Leyes y pactos", "Laws and pacts", "Gesetze und Bündnisse", "Lois et accords", "Leis e pactos"],
  ["Tu gobierno", "Your government", "Deine Regierung", "Votre gouvernement", "Seu governo"],
  ["Tus votantes", "Your voters", "Deine Wähler", "Vos électeurs", "Seus eleitores"],
  ["El mundo", "The world", "Die Welt", "Le monde", "O mundo"],
  ["Fin", "The end", "Ende", "Fin", "Fim"],
  ["Llévame allí", "Take me there", "Bring mich hin", "Emmenez-moi", "Leve-me lá"],
  ["Simple · unos 7 minutos", "Simple · about 7 minutes", "Einfach · etwa 7 Minuten", "Simple · environ 7 minutes", "Simples · cerca de 7 minutos"],
  ["Empiezas ya en el gobierno y te llevo pestaña por pestaña: el capital político, construir, aprobar una ley, pactar, nombrar un ministro y dar un mitin.",
    "You start already in government and I take you tab by tab: political capital, building, passing a law, making a pact, appointing a minister and holding a rally.",
    "Du beginnst schon an der Regierung und ich führe dich Reiter für Reiter: politisches Kapital, bauen, ein Gesetz verabschieden, ein Bündnis schließen, einen Minister ernennen und eine Kundgebung abhalten.",
    "Vous commencez déjà au gouvernement et je vous guide onglet par onglet : le capital politique, construire, faire voter une loi, conclure un accord, nommer un ministre et tenir un meeting.",
    "Você começa já no governo e eu levo você aba por aba: o capital político, construir, aprovar uma lei, fechar um pacto, nomear um ministro e fazer um comício."],
  ["Desde cero: creas tu personaje y tu partido, empiezas de diputado, te ganas el partido, haces campaña, negocias la investidura y gobiernas, con todo explicado a fondo.",
    "From scratch: you create your character and your party, start as an MP, win over the party, campaign, negotiate the investiture and govern, with everything explained in depth.",
    "Von null an: Du erstellst deine Figur und deine Partei, beginnst als Abgeordneter, gewinnst die Partei für dich, machst Wahlkampf, verhandelst die Regierungsbildung und regierst – alles ausführlich erklärt.",
    "À partir de zéro : vous créez votre personnage et votre parti, débutez comme député, gagnez le parti, faites campagne, négociez l'investiture et gouvernez, avec tout expliqué en détail.",
    "Do zero: você cria seu personagem e seu partido, começa como deputado, conquista o partido, faz campanha, negocia a investidura e governa, com tudo explicado a fundo."],

  // Tareas
  ["Elige una de tus provincias", "Choose one of your provinces", "Wähle eine deiner Provinzen", "Choisissez une de vos provinces", "Escolha uma das suas províncias"],
  ["Construye un edificio", "Build a building", "Baue ein Gebäude", "Construisez un bâtiment", "Construa um edifício"],
  ["Propón una ley", "Propose a law", "Schlage ein Gesetz vor", "Proposez une loi", "Proponha uma lei"],
  ["Lleva la ley a votación", "Put the law to a vote", "Bring das Gesetz zur Abstimmung", "Soumettez la loi au vote", "Leve a lei a votação"],
  ["Cierra un pacto con otro partido", "Make a pact with another party", "Schließe ein Bündnis mit einer anderen Partei", "Concluez un accord avec un autre parti", "Feche um pacto com outro partido"],
  ["Nombra a un ministro", "Appoint a minister", "Ernenne einen Minister", "Nommez un ministre", "Nomeie um ministro"],
  ["Da un mitin", "Hold a rally", "Halte eine Kundgebung ab", "Tenez un meeting", "Faça um comício"],
  ["Pulsa el botón dorado", "Click the golden button", "Klicke auf die goldene Schaltfläche", "Cliquez sur le bouton doré", "Clique no botão dourado"],
  ["Empieza la carrera", "Start the career", "Beginne die Karriere", "Commencez la carrière", "Comece a carreira"],
  ["Haz una acción de diputado", "Take an MP action", "Führe eine Abgeordneten-Aktion aus", "Faites une action de député", "Faça uma ação de deputado"],
  ["Gana el congreso del partido", "Win the party congress", "Gewinne den Parteitag", "Gagnez le congrès du parti", "Vença o congresso do partido"],
  ["Promete una ley", "Promise a law", "Versprich ein Gesetz", "Promettez une loi", "Prometa uma lei"],
  ["Gana las elecciones y forma gobierno", "Win the election and form a government", "Gewinne die Wahl und bilde eine Regierung", "Gagnez les élections et formez un gouvernement", "Vença as eleições e forme governo"],

  // Dibujos
  ["Tu fama", "Your fame", "Dein Ruf", "Votre renommée", "Sua fama"],
  ["Lo que te quieren los tuyos", "How much your own side likes you", "Wie sehr dich die Deinen mögen", "L'affection des vôtres", "O quanto os seus gostam de você"],
  ["Pagan tus campañas", "They pay for your campaigns", "Bezahlen deine Kampagnen", "Ils paient vos campagnes", "Pagam suas campanhas"],
  ["Paga obras y ejército", "Pays for building and the army", "Bezahlt Bauten und Armee", "Paie les chantiers et l'armée", "Paga obras e exército"],
  ["Da escaños", "Wins seats", "Bringt Sitze", "Donne des sièges", "Dá cadeiras"],
  ["Si se hunde, caes", "If it collapses, you fall", "Bricht sie ein, stürzt du", "Si elle s'effondre, vous tombez", "Se afundar, você cai"],
  ["Tienes {} de {} · +{} al mes", "You have {} of {} · +{} a month", "Du hast {} von {} · +{} pro Monat", "Vous avez {} sur {} · +{} par mois", "Você tem {} de {} · +{} por mês"],
  ["Llevar una ley a votación", "Putting a law to a vote", "Ein Gesetz zur Abstimmung bringen", "Soumettre une loi au vote", "Levar uma lei a votação"],
  ["Negociar un voto", "Negotiating a vote", "Eine Stimme aushandeln", "Négocier un vote", "Negociar um voto"],
  ["Nombrar un ministro", "Appointing a minister", "Einen Minister ernennen", "Nommer un ministre", "Nomear um ministro"],
  ["Cerrar un pacto", "Making a pact", "Ein Bündnis schließen", "Conclure un accord", "Fechar um pacto"],
  ["Dar un mitin", "Holding a rally", "Eine Kundgebung abhalten", "Tenir un meeting", "Fazer um comício"],
  ["Convocar un referéndum", "Calling a referendum", "Ein Referendum ansetzen", "Convoquer un référendum", "Convocar um referendo"],
  ["Declarar una guerra", "Declaring war", "Einen Krieg erklären", "Déclarer une guerre", "Declarar uma guerra"],
  ["Alimentos", "Food", "Nahrung", "Nourriture", "Alimentos"],
  ["Materias", "Raw materials", "Rohstoffe", "Matières", "Matérias"],
  ["Bienes", "Goods", "Waren", "Biens", "Bens"],
  ["Tú y tus socios: {} de {} escaños · mayoría absoluta: {}", "You and your partners: {} of {} seats · absolute majority: {}", "Du und deine Partner: {} von {} Sitzen · absolute Mehrheit: {}", "Vous et vos partenaires : {} sièges sur {} · majorité absolue : {}", "Você e seus parceiros: {} de {} cadeiras · maioria absoluta: {}"],
  ["Tu partido: {} de {} escaños · mayoría absoluta: {}", "Your party: {} of {} seats · absolute majority: {}", "Deine Partei: {} von {} Sitzen · absolute Mehrheit: {}", "Votre parti : {} sièges sur {} · majorité absolue : {}", "Seu partido: {} de {} cadeiras · maioria absoluta: {}"],
  ["Democracias", "Democracies", "Demokratien", "Démocraties", "Democracias"],
  ["Votan y cambian", "They vote and change", "Wählen und wechseln", "Elles votent et changent", "Votam e mudam"],
  ["Dictaduras", "Dictatorships", "Diktaturen", "Dictatures", "Ditaduras"],
  ["Pueden caer", "They can fall", "Können stürzen", "Elles peuvent tomber", "Podem cair"],
  ["Monarquías", "Monarchies", "Monarchien", "Monarchies", "Monarquias"],
  ["O repúblicas", "Or republics", "Oder Republiken", "Ou républiques", "Ou repúblicas"],
  ["Líder del partido", "Party leader", "Parteichef", "Chef du parti", "Líder do partido"],
  ["Presidente", "President", "Präsident", "Président", "Presidente"],
  ["De diputado a presidente", "From MP to president", "Vom Abgeordneten zum Präsidenten", "De député à président", "De deputado a presidente"],
  ["Mandas desde el principio", "In charge from the start", "Von Anfang an am Ruder", "Aux commandes dès le début", "No comando desde o início"],
  ["Provincial", "Provincial", "Provinzpartei", "Provincial", "Provincial"],
  ["De 0 escaños a todo el país", "From 0 seats to the whole country", "Von 0 Sitzen zum ganzen Land", "De 0 siège à tout le pays", "De 0 cadeiras ao país inteiro"],

  // Pasos del gobierno
  ["Acabas de llegar al gobierno. Cada turno es un mes. Te voy a llevar de la mano por cada pestaña: yo te explico y tú lo pruebas. Verás construir, aprobar leyes, pactar, formar gobierno y ganarte a los votantes.",
    "You have just come to power. Each turn is one month. I will walk you through every tab: I explain and you try it. You will build, pass laws, make pacts, form a cabinet and win over voters.",
    "Du bist gerade an die Regierung gekommen. Jede Runde ist ein Monat. Ich führe dich an der Hand durch jeden Reiter: Ich erkläre, du probierst es aus. Du wirst bauen, Gesetze verabschieden, Bündnisse schließen, ein Kabinett bilden und Wähler gewinnen.",
    "Vous venez d'arriver au gouvernement. Chaque tour est un mois. Je vous guide onglet par onglet : j'explique et vous essayez. Vous allez construire, faire voter des lois, conclure des accords, former un gouvernement et gagner les électeurs.",
    "Você acaba de chegar ao governo. Cada turno é um mês. Vou levar você pela mão por cada aba: eu explico e você experimenta. Você vai construir, aprovar leis, fechar pactos, formar governo e conquistar os eleitores."],
  ["Arriba está siempre lo que más importa. Puedes pulsar cada cifra para ver de dónde sale.",
    "The things that matter most are always at the top. You can click each figure to see where it comes from.",
    "Oben steht immer das Wichtigste. Du kannst jeden Wert anklicken, um zu sehen, woher er kommt.",
    "Le plus important est toujours en haut. Vous pouvez cliquer sur chaque chiffre pour voir d'où il vient.",
    "No topo está sempre o que mais importa. Você pode clicar em cada número para ver de onde ele vem."],
  ["El capital político", "Political capital", "Politisches Kapital", "Le capital politique", "O capital político"],
  ["Es tu energía para decidir. <b>Casi todo lo importante lo gasta</b> y cada mes recuperas un poco. Si te quedas sin él toca esperar al mes siguiente, así que elige bien en qué lo usas.",
    "It is your energy for making decisions. <b>Almost everything important spends it</b> and you get a little back each month. If you run out you have to wait for next month, so choose carefully what you use it on.",
    "Es ist deine Energie für Entscheidungen. <b>Fast alles Wichtige verbraucht es</b>, und jeden Monat bekommst du etwas zurück. Geht es dir aus, musst du bis zum nächsten Monat warten – überleg dir also gut, wofür du es einsetzt.",
    "C'est votre énergie pour décider. <b>Presque tout ce qui compte en consomme</b> et vous en récupérez un peu chaque mois. Si vous n'en avez plus, il faut attendre le mois suivant : choisissez bien à quoi vous l'utilisez.",
    "É a sua energia para decidir. <b>Quase tudo o que importa a gasta</b> e a cada mês você recupera um pouco. Se ficar sem, é preciso esperar o mês seguinte, então escolha bem em que usá-la."],
  ["Tus provincias", "Your provinces", "Deine Provinzen", "Vos provinces", "Suas províncias"],
  ["Te he llevado a <b>Provincias</b>. Tu país se divide en provincias, cada una con su gente y sus recursos. Pulsa una de las tuyas, en el mapa o en la lista.",
    "I have taken you to <b>Provinces</b>. Your country is divided into provinces, each with its own people and resources. Click one of yours, on the map or in the list.",
    "Ich habe dich zu <b>Provinzen</b> gebracht. Dein Land ist in Provinzen eingeteilt, jede mit eigenen Menschen und Rohstoffen. Klicke auf eine deiner Provinzen, auf der Karte oder in der Liste.",
    "Je vous ai amené à <b>Provinces</b>. Votre pays est divisé en provinces, chacune avec ses habitants et ses ressources. Cliquez sur l'une des vôtres, sur la carte ou dans la liste.",
    "Levei você a <b>Províncias</b>. Seu país se divide em províncias, cada uma com seu povo e seus recursos. Clique em uma das suas, no mapa ou na lista."],
  ["Te he llevado a <b>Economía</b>: aquí ves de dónde sale y a dónde va el dinero. <b>Mejores inversiones</b> te dice qué obra se paga antes. Más abajo puedes cambiar los <b>impuestos</b> y pedir <b>préstamos</b>. Si la deuda pasa de −400, tu gobierno cae.",
    "I have taken you to <b>Economy</b>: here you see where the money comes from and where it goes. <b>Best investments</b> tells you which project pays for itself soonest. Further down you can change <b>taxes</b> and take out <b>loans</b>. If debt goes past −400, your government falls.",
    "Ich habe dich zu <b>Wirtschaft</b> gebracht: Hier siehst du, woher das Geld kommt und wohin es fließt. <b>Beste Investitionen</b> zeigt dir, welches Bauprojekt sich am schnellsten bezahlt macht. Weiter unten kannst du die <b>Steuern</b> ändern und <b>Kredite</b> aufnehmen. Übersteigen die Schulden −400, stürzt deine Regierung.",
    "Je vous ai amené à <b>Économie</b> : vous voyez ici d'où vient l'argent et où il va. <b>Meilleurs investissements</b> vous indique quel chantier est rentabilisé le plus vite. Plus bas, vous pouvez modifier les <b>impôts</b> et demander des <b>prêts</b>. Si la dette dépasse −400, votre gouvernement tombe.",
    "Levei você a <b>Economia</b>: aqui você vê de onde sai e para onde vai o dinheiro. <b>Melhores investimentos</b> diz qual obra se paga antes. Mais abaixo você pode mudar os <b>impostos</b> e pedir <b>empréstimos</b>. Se a dívida passar de −400, seu governo cai."],
  ["Te he llevado al <b>Parlamento</b>. Hay <b>{} escaños</b> y la mayoría absoluta son <b>{}</b>. Cada color es un partido: una ley sale si tiene más votos a favor que en contra.",
    "I have taken you to <b>Parliament</b>. There are <b>{} seats</b> and an absolute majority is <b>{}</b>. Each colour is a party: a law passes if it gets more votes for than against.",
    "Ich habe dich ins <b>Parlament</b> gebracht. Es gibt <b>{} Sitze</b> und die absolute Mehrheit liegt bei <b>{}</b>. Jede Farbe ist eine Partei: Ein Gesetz kommt durch, wenn es mehr Ja- als Nein-Stimmen hat.",
    "Je vous ai amené au <b>Parlement</b>. Il y a <b>{} sièges</b> et la majorité absolue est de <b>{}</b>. Chaque couleur est un parti : une loi passe si elle obtient plus de voix pour que contre.",
    "Levei você ao <b>Parlamento</b>. Há <b>{} cadeiras</b> e a maioria absoluta são <b>{}</b>. Cada cor é um partido: uma lei passa se tiver mais votos a favor do que contra."],
  ["Más abajo están las leyes: cada una dice a quién gusta y qué cambia. Las que encajan con las ideas de tu partido salen mejor. Pulsa <b>Proponer</b> en la que quieras.",
    "The laws are further down: each one says who likes it and what it changes. Those that fit your party's ideas go more smoothly. Click <b>Propose</b> on the one you want.",
    "Weiter unten stehen die Gesetze: Jedes sagt, wem es gefällt und was es ändert. Die, die zu den Ideen deiner Partei passen, gehen leichter durch. Klicke bei einem beliebigen auf <b>Vorschlagen</b>.",
    "Les lois sont plus bas : chacune indique à qui elle plaît et ce qu'elle change. Celles qui correspondent aux idées de votre parti passent mieux. Cliquez sur <b>Proposer</b> pour celle que vous voulez.",
    "Mais abaixo estão as leis: cada uma diz a quem agrada e o que muda. As que combinam com as ideias do seu partido saem melhor. Clique em <b>Propor</b> na que quiser."],
  ["Sin {} escaños propios necesitas <b>socios</b>. Solo pactan contigo los partidos de ideas cercanas y que no tengan más escaños que tú. Cada socio pide <b>una ley</b> a cambio: si no la apruebas en {} meses, se va. Pulsa <b>Pactar</b> con uno.",
    "Without {} seats of your own you need <b>partners</b>. Only parties with ideas close to yours, and with no more seats than you, will make a pact. Each partner asks for <b>one law</b> in return: if you do not pass it within {} months, they leave. Click <b>Strike a pact</b> with one.",
    "Ohne {} eigene Sitze brauchst du <b>Partner</b>. Nur Parteien mit ähnlichen Ideen und nicht mehr Sitzen als du schließen ein Bündnis mit dir. Jeder Partner verlangt dafür <b>ein Gesetz</b>: Verabschiedest du es nicht innerhalb von {} Monaten, geht er. Klicke bei einer auf <b>Bündnis schließen</b>.",
    "Sans {} sièges à vous, il vous faut des <b>partenaires</b>. Seuls les partis aux idées proches, et qui n'ont pas plus de sièges que vous, concluent un accord. Chaque partenaire demande <b>une loi</b> en échange : si vous ne la faites pas voter en {} mois, il s'en va. Cliquez sur <b>Conclure un accord</b> avec l'un d'eux.",
    "Sem {} cadeiras próprias você precisa de <b>parceiros</b>. Só fazem pacto com você os partidos de ideias próximas e que não tenham mais cadeiras que você. Cada parceiro pede <b>uma lei</b> em troca: se você não a aprovar em {} meses, ele sai. Clique em <b>Pactuar</b> com um."],
  ["Mayoría o minoría", "Majority or minority", "Mehrheit oder Minderheit", "Majorité ou minorité", "Maioria ou minoria"],
  ["Tus socios votan tus leyes casi siempre. Si entre todos sumáis {} escaños tienes <b>mayoría absoluta</b>. Con menos gobiernas <b>en minoría</b>: pierdes estabilidad y, si los partidos que se llevan mal contigo suman {} y tu popularidad baja de 50, te presentan una <b>moción de censura</b>.",
    "Your partners vote for your laws almost every time. If together you reach {} seats you have an <b>absolute majority</b>. With fewer you govern <b>in a minority</b>: you lose stability and, if the parties on bad terms with you add up to {} and your popularity drops below 50, they table a <b>no-confidence motion</b>.",
    "Deine Partner stimmen fast immer für deine Gesetze. Kommt ihr zusammen auf {} Sitze, hast du die <b>absolute Mehrheit</b>. Mit weniger regierst du <b>in der Minderheit</b>: Du verlierst Stabilität, und wenn die Parteien, die schlecht auf dich zu sprechen sind, auf {} kommen und deine Beliebtheit unter 50 fällt, stellen sie ein <b>Misstrauensvotum</b>.",
    "Vos partenaires votent presque toujours vos lois. Si vous totalisez ensemble {} sièges, vous avez la <b>majorité absolue</b>. Avec moins, vous gouvernez <b>en minorité</b> : vous perdez de la stabilité et, si les partis en mauvais termes avec vous totalisent {} et que votre popularité passe sous 50, ils déposent une <b>motion de censure</b>.",
    "Seus parceiros votam suas leis quase sempre. Se juntos vocês somam {} cadeiras, você tem <b>maioria absoluta</b>. Com menos, governa <b>em minoria</b>: perde estabilidade e, se os partidos que se dão mal com você somarem {} e sua popularidade cair abaixo de 50, eles apresentam uma <b>moção de censura</b>."],
  ["Forma tu gabinete", "Form your cabinet", "Bilde dein Kabinett", "Formez votre gouvernement", "Forme seu gabinete"],
  ["Te he llevado a <b>Gobierno</b>. Elige una cartera y nombra a un ministro: cada uno te da una ventaja todos los meses. Si es de otro partido, ese partido te apoyará más.",
    "I have taken you to <b>Government</b>. Choose a portfolio and appoint a minister: each one gives you a benefit every month. If they are from another party, that party will support you more.",
    "Ich habe dich zu <b>Regierung</b> gebracht. Wähle ein Ressort und ernenne einen Minister: Jeder bringt dir jeden Monat einen Vorteil. Kommt er aus einer anderen Partei, unterstützt dich diese Partei stärker.",
    "Je vous ai amené à <b>Gouvernement</b>. Choisissez un portefeuille et nommez un ministre : chacun vous apporte un avantage tous les mois. S'il vient d'un autre parti, ce parti vous soutiendra davantage.",
    "Levei você a <b>Governo</b>. Escolha uma pasta e nomeie um ministro: cada um dá uma vantagem todos os meses. Se for de outro partido, esse partido vai apoiar você mais."],
  ["Monarquía o república", "Monarchy or republic", "Monarchie oder Republik", "Monarchie ou république", "Monarquia ou república"],
  ["Tu país es una <b>monarquía</b>. Cada forma del Estado gusta a unos grupos y molesta a otros, y tu partido tiene su postura. Gobernando puedes convocar un <b>referéndum</b>, uno por legislatura: gane quien gane, el resultado se aplica.",
    "Your country is a <b>monarchy</b>. Each form of state pleases some groups and annoys others, and your party has its own stance. In government you can call a <b>referendum</b>, one per term: whoever wins, the result is applied.",
    "Dein Land ist eine <b>Monarchie</b>. Jede Staatsform gefällt manchen Gruppen und ärgert andere, und deine Partei hat ihre Haltung dazu. An der Regierung kannst du ein <b>Referendum</b> ansetzen, eines pro Legislaturperiode: Wer auch gewinnt, das Ergebnis gilt.",
    "Votre pays est une <b>monarchie</b>. Chaque forme de l'État plaît à certains groupes et en irrite d'autres, et votre parti a sa position. Au gouvernement, vous pouvez convoquer un <b>référendum</b>, un par législature : quel que soit le vainqueur, le résultat s'applique.",
    "Seu país é uma <b>monarquia</b>. Cada forma de Estado agrada a uns grupos e incomoda outros, e seu partido tem sua posição. Governando, você pode convocar um <b>referendo</b>, um por legislatura: ganhe quem ganhar, o resultado se aplica."],
  ["Tu país es una <b>república</b>. Cada forma del Estado gusta a unos grupos y molesta a otros, y tu partido tiene su postura. Gobernando puedes convocar un <b>referéndum</b>, uno por legislatura: gane quien gane, el resultado se aplica.",
    "Your country is a <b>republic</b>. Each form of state pleases some groups and annoys others, and your party has its own stance. In government you can call a <b>referendum</b>, one per term: whoever wins, the result is applied.",
    "Dein Land ist eine <b>Republik</b>. Jede Staatsform gefällt manchen Gruppen und ärgert andere, und deine Partei hat ihre Haltung dazu. An der Regierung kannst du ein <b>Referendum</b> ansetzen, eines pro Legislaturperiode: Wer auch gewinnt, das Ergebnis gilt.",
    "Votre pays est une <b>république</b>. Chaque forme de l'État plaît à certains groupes et en irrite d'autres, et votre parti a sa position. Au gouvernement, vous pouvez convoquer un <b>référendum</b>, un par législature : quel que soit le vainqueur, le résultat s'applique.",
    "Seu país é uma <b>república</b>. Cada forma de Estado agrada a uns grupos e incomoda outros, e seu partido tem sua posição. Governando, você pode convocar um <b>referendo</b>, um por legislatura: ganhe quem ganhar, o resultado se aplica."],
  ["Cuatro grupos, {} escaños", "Four groups, {} seats", "Vier Gruppen, {} Sitze", "Quatre groupes, {} sièges", "Quatro grupos, {} cadeiras"],
  ["Te he llevado a <b>Sociedad</b>. Obreros, empresarios, campesinos y jóvenes: su apoyo decide cuántos escaños sacas en las elecciones. Aquí ves qué le gusta y qué le molesta a cada uno.",
    "I have taken you to <b>Society</b>. Workers, business owners, farmers and young people: their support decides how many seats you win at the election. Here you see what each one likes and dislikes.",
    "Ich habe dich zu <b>Gesellschaft</b> gebracht. Arbeiter, Unternehmer, Bauern und junge Leute: Ihre Unterstützung entscheidet, wie viele Sitze du bei der Wahl holst. Hier siehst du, was jeder Gruppe gefällt und was sie stört.",
    "Je vous ai amené à <b>Société</b>. Ouvriers, entrepreneurs, paysans et jeunes : leur soutien décide du nombre de sièges que vous obtenez aux élections. Vous voyez ici ce qui plaît et ce qui déplaît à chacun.",
    "Levei você a <b>Sociedade</b>. Operários, empresários, camponeses e jovens: o apoio deles decide quantas cadeiras você conquista nas eleições. Aqui você vê do que cada um gosta e o que o incomoda."],
  ["Gánate a un grupo", "Win over a group", "Gewinne eine Gruppe für dich", "Gagnez un groupe", "Conquiste um grupo"],
  ["Un <b>mitin</b> sube al momento el apoyo de un grupo. Cuesta 1 de capital político y algo de dinero, y solo puedes dar uno al mes. Elige a quién quieres convencer.",
    "A <b>rally</b> raises a group's support straight away. It costs 1 political capital and some money, and you can only hold one a month. Choose who you want to win over.",
    "Eine <b>Kundgebung</b> hebt die Unterstützung einer Gruppe sofort. Sie kostet 1 politisches Kapital und etwas Geld, und du kannst nur eine pro Monat abhalten. Wähle, wen du überzeugen willst.",
    "Un <b>meeting</b> fait monter tout de suite le soutien d'un groupe. Il coûte 1 de capital politique et un peu d'argent, et vous ne pouvez en tenir qu'un par mois. Choisissez qui vous voulez convaincre.",
    "Um <b>comício</b> aumenta na hora o apoio de um grupo. Custa 1 de capital político e algum dinheiro, e você só pode fazer um por mês. Escolha quem quer convencer."],
  ["Te he llevado a <b>Diplomacia</b>. Los demás países también tienen política: celebran elecciones, cambian de gobierno, sufren golpes y sus dictaduras pueden caer. Quién manda cambia cómo te miran y lo que rinde el comercio. Con buena relación firmas <b>tratados</b> (dan dinero) y <b>alianzas</b>.",
    "I have taken you to <b>Diplomacy</b>. Other countries have politics too: they hold elections, change governments, suffer coups, and their dictatorships can fall. Who is in charge changes how they see you and how much trade brings in. With good relations you sign <b>treaties</b> (they bring money) and <b>alliances</b>.",
    "Ich habe dich zu <b>Diplomatie</b> gebracht. Auch die anderen Länder haben Politik: Sie halten Wahlen ab, wechseln die Regierung, erleben Putsche, und ihre Diktaturen können stürzen. Wer regiert, ändert, wie sie dich sehen und was der Handel einbringt. Bei guten Beziehungen schließt du <b>Verträge</b> (bringen Geld) und <b>Allianzen</b>.",
    "Je vous ai amené à <b>Diplomatie</b>. Les autres pays ont aussi leur politique : ils organisent des élections, changent de gouvernement, subissent des coups d'État, et leurs dictatures peuvent tomber. Qui gouverne change la façon dont ils vous voient et ce que rapporte le commerce. Avec de bonnes relations, vous signez des <b>traités</b> (ils rapportent de l'argent) et des <b>alliances</b>.",
    "Levei você a <b>Diplomacia</b>. Os outros países também têm política: fazem eleições, mudam de governo, sofrem golpes e suas ditaduras podem cair. Quem manda muda como eles veem você e quanto rende o comércio. Com boa relação você assina <b>tratados</b> (dão dinheiro) e <b>alianças</b>."],
  ["Te he llevado a <b>Defensa</b>. Cada regimiento cuesta dinero al mes. Con ellos te defiendes y, si declaras una guerra, atacas provincias enemigas: lo que ocupes puedes quedártelo al firmar la paz. Si conquistas todos los países, ganas la partida; si ocupan todo el tuyo, la pierdes.",
    "I have taken you to <b>Defence</b>. Each regiment costs money every month. You use them to defend yourself and, if you declare war, to attack enemy provinces: what you occupy you can keep when you sign the peace. If you conquer every country, you win the game; if yours is fully occupied, you lose it.",
    "Ich habe dich zu <b>Verteidigung</b> gebracht. Jedes Regiment kostet monatlich Geld. Mit ihnen verteidigst du dich und greifst, wenn du einen Krieg erklärst, feindliche Provinzen an: Was du besetzt, kannst du beim Friedensschluss behalten. Eroberst du alle Länder, gewinnst du das Spiel; wird dein ganzes Land besetzt, verlierst du es.",
    "Je vous ai amené à <b>Défense</b>. Chaque régiment coûte de l'argent chaque mois. Ils servent à vous défendre et, si vous déclarez une guerre, à attaquer des provinces ennemies : ce que vous occupez, vous pouvez le garder en signant la paix. Si vous conquérez tous les pays, vous gagnez la partie ; si le vôtre est entièrement occupé, vous la perdez.",
    "Levei você a <b>Defesa</b>. Cada regimento custa dinheiro por mês. Com eles você se defende e, se declarar uma guerra, ataca províncias inimigas: o que ocupar, pode manter ao assinar a paz. Se conquistar todos os países, vence a partida; se ocuparem todo o seu, perde."],
  ["Cuando acabes lo que quieras hacer, pulsa <b>Siguiente mes</b> (o la barra espaciadora): cobras impuestos, avanzan las obras, recuperas capital político y pasan cosas.",
    "When you have done what you want, click <b>Next month</b> (or press the space bar): you collect taxes, building work moves on, you regain political capital and things happen.",
    "Wenn du fertig bist, klicke auf <b>Nächster Monat</b> (oder drücke die Leertaste): Du kassierst Steuern, die Bauten kommen voran, du erhältst politisches Kapital zurück und es passiert einiges.",
    "Quand vous avez fini, cliquez sur <b>Mois suivant</b> (ou appuyez sur la barre d'espace) : vous percevez les impôts, les chantiers avancent, vous récupérez du capital politique et il se passe des choses.",
    "Quando terminar o que quiser fazer, clique em <b>Próximo mês</b> (ou na barra de espaço): você cobra impostos, as obras avançam, você recupera capital político e coisas acontecem."],
  ["Habrá elecciones cada {} meses. Si nadie llega a {} escaños habrá <b>investidura</b>: gobierna el bloque que más sume. Si pierdes no se acaba la partida: pasas a la oposición y tu partido te marca una directiva. Para aprender la carrera de diputado, prueba el <b>tutorial completo</b>. Suerte.",
    "There will be an election every {} months. If nobody reaches {} seats there will be an <b>investiture</b>: the bloc with the most seats governs. If you lose, the game is not over: you go into opposition and your party sets you a directive. To learn the MP career, try the <b>full tutorial</b>. Good luck.",
    "Alle {} Monate wird gewählt. Erreicht niemand {} Sitze, kommt es zur <b>Regierungsbildung</b>: Es regiert der Block mit den meisten Sitzen. Verlierst du, ist das Spiel nicht vorbei: Du gehst in die Opposition und deine Partei gibt dir eine Vorgabe. Um die Abgeordnetenkarriere zu lernen, probiere das <b>vollständige Tutorial</b>. Viel Glück.",
    "Il y aura des élections tous les {} mois. Si personne n'atteint {} sièges, il y aura une <b>investiture</b> : le bloc qui totalise le plus de sièges gouverne. Si vous perdez, la partie n'est pas finie : vous passez dans l'opposition et votre parti vous fixe une directive. Pour apprendre la carrière de député, essayez le <b>tutoriel complet</b>. Bonne chance.",
    "Haverá eleições a cada {} meses. Se ninguém chegar a {} cadeiras, haverá <b>investidura</b>: governa o bloco que somar mais. Se você perder, a partida não acaba: você passa para a oposição e seu partido define uma diretriz. Para aprender a carreira de deputado, experimente o <b>tutorial completo</b>. Boa sorte."],

  // Tutorial completo: crear la partida
  ["Tres formas de empezar", "Three ways to start", "Drei Arten zu beginnen", "Trois façons de commencer", "Três formas de começar"],
  ["En <b>Carrera política</b> empiezas de diputado raso. En <b>Gobierno directo</b> empiezas ya mandando. En <b>Partido provincial</b> fundas un partido en una sola provincia y creces abriendo sedes. En este tutorial haremos la carrera entera.",
    "In <b>Political career</b> you start as a backbench MP. In <b>Straight to government</b> you start already in charge. In <b>Provincial party</b> you found a party in a single province and grow by opening offices. In this tutorial we will do the whole career.",
    "In <b>Politische Karriere</b> beginnst du als einfacher Abgeordneter. In <b>Direkt regieren</b> beginnst du schon an der Macht. In <b>Provinzpartei</b> gründest du eine Partei in einer einzigen Provinz und wächst, indem du Büros eröffnest. In diesem Tutorial machen wir die ganze Karriere.",
    "Dans <b>Carrière politique</b>, vous débutez comme simple député. Dans <b>Gouvernement direct</b>, vous commencez déjà aux commandes. Dans <b>Parti provincial</b>, vous fondez un parti dans une seule province et grandissez en ouvrant des permanences. Dans ce tutoriel, nous ferons toute la carrière.",
    "Em <b>Carreira política</b> você começa como deputado raso. Em <b>Governo direto</b> começa já no comando. Em <b>Partido provincial</b> você funda um partido em uma única província e cresce abrindo sedes. Neste tutorial faremos a carreira inteira."],
  ["Si <b>creas el tuyo</b> eliges nombre, insignia e ideas. Si <b>te unes</b> a uno que ya existe, heredas sus votantes y sus ideas tal cual. Elige lo que prefieras.",
    "If you <b>create your own</b> you choose its name, badge and ideas. If you <b>join</b> an existing one, you inherit its voters and its ideas as they are. Choose whichever you prefer.",
    "Wenn du <b>deine eigene gründest</b>, wählst du Namen, Abzeichen und Ideen. Wenn du einer bestehenden <b>beitrittst</b>, übernimmst du ihre Wähler und Ideen unverändert. Wähle, was dir lieber ist.",
    "Si vous <b>créez le vôtre</b>, vous choisissez le nom, l'insigne et les idées. Si vous en <b>rejoignez</b> un qui existe déjà, vous héritez tels quels de ses électeurs et de ses idées. Choisissez ce que vous préférez.",
    "Se você <b>criar o seu</b>, escolhe nome, emblema e ideias. Se <b>entrar</b> em um que já existe, herda seus eleitores e suas ideias como estão. Escolha o que preferir."],
  ["Diseña tu insignia", "Design your badge", "Gestalte dein Abzeichen", "Dessinez votre insigne", "Desenhe seu emblema"],
  ["Ponle nombre a tu partido y diseña su <b>insignia</b>: forma, fondo de dos colores, un símbolo entre decenas o tus propias letras. Arriba ves cómo queda: así saldrá en el hemiciclo y en el mapa electoral.",
    "Name your party and design its <b>badge</b>: shape, two-colour background, one of dozens of symbols or your own letters. You can see the result above: that is how it will look in the chamber and on the electoral map.",
    "Gib deiner Partei einen Namen und gestalte ihr <b>Abzeichen</b>: Form, zweifarbiger Hintergrund, eines von Dutzenden Symbolen oder eigene Buchstaben. Oben siehst du das Ergebnis: So erscheint es im Plenarsaal und auf der Wahlkarte.",
    "Donnez un nom à votre parti et dessinez son <b>insigne</b> : forme, fond bicolore, un symbole parmi des dizaines ou vos propres lettres. Vous voyez le résultat en haut : c'est ainsi qu'il apparaîtra dans l'hémicycle et sur la carte électorale.",
    "Dê um nome ao seu partido e desenhe seu <b>emblema</b>: forma, fundo de duas cores, um símbolo entre dezenas ou suas próprias letras. Acima você vê como fica: é assim que vai aparecer no hemiciclo e no mapa eleitoral."],
  ["Costumbres y corona", "Social values and the crown", "Gesellschaft und Krone", "Mœurs et couronne", "Costumes e coroa"],
  ["Un poco más abajo eliges cómo de <b>progresista o conservador</b> es tu partido y si defiende la <b>monarquía</b> o la <b>república</b>. Importa mucho: los partidos solo pactan con quien piensa parecido.",
    "A little further down you choose how <b>progressive or conservative</b> your party is and whether it backs the <b>monarchy</b> or the <b>republic</b>. It matters a lot: parties only make pacts with those who think alike.",
    "Etwas weiter unten wählst du, wie <b>progressiv oder konservativ</b> deine Partei ist und ob sie für die <b>Monarchie</b> oder die <b>Republik</b> eintritt. Das ist wichtig: Parteien schließen nur Bündnisse mit denen, die ähnlich denken.",
    "Un peu plus bas, vous choisissez à quel point votre parti est <b>progressiste ou conservateur</b> et s'il défend la <b>monarchie</b> ou la <b>république</b>. C'est très important : les partis ne concluent d'accord qu'avec ceux qui pensent comme eux.",
    "Um pouco mais abaixo você escolhe o quanto seu partido é <b>progressista ou conservador</b> e se defende a <b>monarquia</b> ou a <b>república</b>. Importa muito: os partidos só fazem pacto com quem pensa parecido."],
  ["El partido al que te unes ya tiene su postura sobre las costumbres y sobre la corona. Importa mucho: los partidos solo pactan con quien piensa parecido.",
    "The party you are joining already has its stance on social values and on the crown. It matters a lot: parties only make pacts with those who think alike.",
    "Die Partei, der du beitrittst, hat bereits ihre Haltung zu Gesellschaft und Krone. Das ist wichtig: Parteien schließen nur Bündnisse mit denen, die ähnlich denken.",
    "Le parti que vous rejoignez a déjà sa position sur les mœurs et sur la couronne. C'est très important : les partis ne concluent d'accord qu'avec ceux qui pensent comme eux.",
    "O partido em que você entra já tem sua posição sobre os costumes e sobre a coroa. Importa muito: os partidos só fazem pacto com quem pensa parecido."],
  ["Ponle nombre y color a tu país y elige si es una <b>monarquía</b> o una <b>república</b>. El <b>tamaño del mundo</b> marca cuántos países hay, y cada <b>número de mapa</b> genera uno distinto (a la derecha lo ves). Con más <b>partidos</b> en el parlamento, el voto se reparte más y hay que pactar más.",
    "Give your country a name and a colour and choose whether it is a <b>monarchy</b> or a <b>republic</b>. The <b>world size</b> sets how many countries there are, and each <b>map number</b> generates a different one (you can see it on the right). With more <b>parties</b> in parliament, the vote is more split and you have to make more pacts.",
    "Gib deinem Land Namen und Farbe und wähle, ob es eine <b>Monarchie</b> oder eine <b>Republik</b> ist. Die <b>Weltgröße</b> legt fest, wie viele Länder es gibt, und jede <b>Kartennummer</b> erzeugt eine andere Welt (rechts siehst du sie). Mit mehr <b>Parteien</b> im Parlament verteilen sich die Stimmen stärker und du musst mehr Bündnisse schließen.",
    "Donnez un nom et une couleur à votre pays et choisissez s'il s'agit d'une <b>monarchie</b> ou d'une <b>république</b>. La <b>taille du monde</b> fixe le nombre de pays, et chaque <b>numéro de carte</b> en génère une différente (vous la voyez à droite). Avec plus de <b>partis</b> au parlement, les voix se dispersent davantage et il faut conclure plus d'accords.",
    "Dê nome e cor ao seu país e escolha se ele é uma <b>monarquia</b> ou uma <b>república</b>. O <b>tamanho do mundo</b> define quantos países há, e cada <b>número de mapa</b> gera um diferente (você o vê à direita). Com mais <b>partidos</b> no parlamento, o voto se divide mais e é preciso fazer mais pactos."],

  // Tutorial completo: carrera, campaña e investidura
  ["Mira qué votaría cada partido y <b>negocia</b> si te falta alguno. Ojo: con menos de {} de apoyo en el partido, tu propio grupo se abstiene. Si la ley sale, ganas prestigio, apoyo en el partido e imagen entre quienes se benefician. Pulsa <b>Llevar a votación</b>.",
    "See how each party would vote and <b>negotiate</b> if you are short of one. Careful: with less than {} party support, your own group abstains. If the law passes, you gain prestige, party support and standing among those who benefit. Click <b>Bring to a vote</b>.",
    "Sieh dir an, wie jede Partei stimmen würde, und <b>verhandle</b>, wenn dir eine fehlt. Achtung: Mit weniger als {} Unterstützung in der Partei enthält sich deine eigene Fraktion. Kommt das Gesetz durch, gewinnst du Ansehen, Unterstützung in der Partei und Ansehen bei denen, die profitieren. Klicke auf <b>Zur Abstimmung bringen</b>.",
    "Regardez comment voterait chaque parti et <b>négociez</b> s'il vous en manque un. Attention : avec moins de {} de soutien dans le parti, votre propre groupe s'abstient. Si la loi passe, vous gagnez du prestige, du soutien dans le parti et de l'image auprès de ceux qui en bénéficient. Cliquez sur <b>Passer au vote</b>.",
    "Veja como cada partido votaria e <b>negocie</b> se faltar algum. Atenção: com menos de {} de apoio no partido, seu próprio grupo se abstém. Se a lei passar, você ganha prestígio, apoio no partido e imagem entre quem se beneficia. Clique em <b>Levar à votação</b>."],
  ["Sigue así: cada mes haz acciones que suban tu apoyo y tu prestigio y pasa de mes. El congreso es en {}: ahora tienes {} y {}, {}. Si lo pierdes, habrá otro más adelante.",
    "Keep going: each month take actions that raise your support and prestige, then move on a month. The congress is in {}: you now have {} and {}, {}. If you lose it, there will be another one later.",
    "Weiter so: Führe jeden Monat Aktionen aus, die deine Unterstützung und dein Ansehen heben, und geh zum nächsten Monat. Der Parteitag ist in {}: Du hast jetzt {} und {}, {}. Verlierst du ihn, gibt es später einen weiteren.",
    "Continuez ainsi : chaque mois, faites des actions qui augmentent votre soutien et votre prestige, puis passez au mois suivant. Le congrès a lieu dans {} : vous avez maintenant {} et {}, {}. Si vous le perdez, il y en aura un autre plus tard.",
    "Continue assim: a cada mês faça ações que aumentem seu apoio e seu prestígio e passe de mês. O congresso é em {}: agora você tem {} e {}, {}. Se perder, haverá outro mais adiante."],
  ["Ya diriges el partido.", "You now lead the party.", "Du führst jetzt die Partei.", "Vous dirigez maintenant le parti.", "Você já dirige o partido."],
  ["Te he llevado a <b>Partido</b>. Dentro de {} los delegados eligen líder. Gana quien llegue con más apoyo: el tuyo es tu <b>apoyo en el partido</b> más una quinta parte de tu <b>prestigio</b>. Las barras comparan lo tuyo con lo de {}.",
    "I have taken you to <b>Party</b>. In {} the delegates choose a leader. Whoever arrives with the most support wins: yours is your <b>party support</b> plus a fifth of your <b>prestige</b>. The bars compare yours with that of {}.",
    "Ich habe dich zu <b>Partei</b> gebracht. In {} wählen die Delegierten den Vorsitz. Es gewinnt, wer mit der meisten Unterstützung antritt: Deine ist deine <b>Unterstützung in der Partei</b> plus ein Fünftel deines <b>Ansehens</b>. Die Balken vergleichen deine Werte mit denen von {}.",
    "Je vous ai amené à <b>Parti</b>. Dans {}, les délégués élisent le chef. Gagne celui qui arrive avec le plus de soutien : le vôtre est votre <b>soutien dans le parti</b> plus un cinquième de votre <b>prestige</b>. Les barres comparent le vôtre à celui de {}.",
    "Levei você a <b>Partido</b>. Dentro de {} os delegados elegem o líder. Vence quem chegar com mais apoio: o seu é o seu <b>apoio no partido</b> mais um quinto do seu <b>prestígio</b>. As barras comparam o seu com o de {}."],
  ["Te he llevado al <b>Parlamento</b>: también puedes legislar sin gobernar. Pulsa <b>Proponer</b> en una ley: si encaja con las ideas de tu partido, mejor.",
    "I have taken you to <b>Parliament</b>: you can legislate without governing too. Click <b>Propose</b> on a law: if it fits your party's ideas, all the better.",
    "Ich habe dich ins <b>Parlament</b> gebracht: Du kannst auch ohne zu regieren Gesetze einbringen. Klicke bei einem Gesetz auf <b>Vorschlagen</b>: Passt es zu den Ideen deiner Partei, umso besser.",
    "Je vous ai amené au <b>Parlement</b> : vous pouvez aussi légiférer sans gouverner. Cliquez sur <b>Proposer</b> pour une loi : si elle correspond aux idées de votre parti, c'est encore mieux.",
    "Levei você ao <b>Parlamento</b>: você também pode legislar sem governar. Clique em <b>Propor</b> em uma lei: se combinar com as ideias do seu partido, melhor."],
  ["Te he llevado a <b>Votantes</b>. Aquí ves cuánto apoya cada grupo a tu partido y por qué. La marca vertical es hacia donde se mueve ese apoyo. Un <b>mitin</b> lo sube al momento, y en la pestaña <b>Mapa</b> ves quién ganaría en cada provincia.",
    "I have taken you to <b>Voters</b>. Here you see how much each group supports your party and why. The vertical mark shows where that support is heading. A <b>rally</b> raises it straight away, and on the <b>Map</b> tab you see who would win in each province.",
    "Ich habe dich zu <b>Wähler</b> gebracht. Hier siehst du, wie stark jede Gruppe deine Partei unterstützt und warum. Die senkrechte Markierung zeigt, wohin sich diese Unterstützung bewegt. Eine <b>Kundgebung</b> hebt sie sofort, und im Reiter <b>Karte</b> siehst du, wer in jeder Provinz gewinnen würde.",
    "Je vous ai amené à <b>Électeurs</b>. Vous voyez ici à quel point chaque groupe soutient votre parti et pourquoi. Le repère vertical indique vers où ce soutien évolue. Un <b>meeting</b> le fait monter tout de suite, et dans l'onglet <b>Carte</b> vous voyez qui gagnerait dans chaque province.",
    "Levei você a <b>Eleitores</b>. Aqui você vê o quanto cada grupo apoia seu partido e por quê. A marca vertical mostra para onde esse apoio se move. Um <b>comício</b> o aumenta na hora, e na aba <b>Mapa</b> você vê quem venceria em cada província."],
  ["Ahora eres la cara de {} y su candidato. Las elecciones son en {}. Con {} escaños gobiernas sin más; si nadie llega, habrá <b>investidura</b> y gobernará el bloque de partidos que más sume. Como líder decides el voto de todo tu grupo y tienes acciones nuevas, como la <b>campaña en medios</b>.",
    "You are now the face of {} and its candidate. The election is in {}. With {} seats you simply govern; if nobody gets there, there will be an <b>investiture</b> and the bloc of parties with the most seats will govern. As leader you decide your whole group's vote and you have new actions, such as the <b>media campaign</b>.",
    "Du bist jetzt das Gesicht von {} und ihr Kandidat. Die Wahl ist in {}. Mit {} Sitzen regierst du einfach; erreicht sie niemand, kommt es zur <b>Regierungsbildung</b>, und es regiert der Parteienblock mit den meisten Sitzen. Als Vorsitzender bestimmst du die Stimme deiner ganzen Fraktion und hast neue Aktionen wie die <b>Medienkampagne</b>.",
    "Vous êtes maintenant le visage de {} et son candidat. Les élections ont lieu dans {}. Avec {} sièges, vous gouvernez sans autre formalité ; si personne n'y parvient, il y aura une <b>investiture</b> et le bloc de partis qui totalise le plus de sièges gouvernera. En tant que chef, vous décidez du vote de tout votre groupe et vous avez de nouvelles actions, comme la <b>campagne médiatique</b>.",
    "Agora você é o rosto de {} e seu candidato. As eleições são em {}. Com {} cadeiras você governa sem mais; se ninguém chegar lá, haverá <b>investidura</b> e governará o bloco de partidos que somar mais. Como líder, você decide o voto de todo o seu grupo e tem ações novas, como a <b>campanha na mídia</b>."],
  ["Te he llevado a <b>Partido</b>. Promete una ley: cada promesa atrae ya a los grupos a los que beneficia; si ganas, tendrás 12 meses para cumplirla o esos grupos se enfadarán.",
    "I have taken you to <b>Party</b>. Promise a law: each promise already attracts the groups it benefits; if you win, you will have 12 months to keep it or those groups will get angry.",
    "Ich habe dich zu <b>Partei</b> gebracht. Versprich ein Gesetz: Jedes Versprechen zieht schon jetzt die Gruppen an, denen es nützt; gewinnst du, hast du 12 Monate, es einzulösen, sonst werden diese Gruppen wütend.",
    "Je vous ai amené à <b>Parti</b>. Promettez une loi : chaque promesse attire déjà les groupes qu'elle avantage ; si vous gagnez, vous aurez 12 mois pour la tenir, sinon ces groupes se fâcheront.",
    "Levei você a <b>Partido</b>. Prometa uma lei: cada promessa já atrai os grupos que ela beneficia; se você vencer, terá 12 meses para cumpri-la ou esses grupos ficarão irritados."],
  ["La investidura", "The investiture", "Die Regierungsbildung", "L'investiture", "A investidura"],
  ["Nadie tiene los {} escaños. Las barras comparan tu bloque con el del rival: pulsa <b>Pactar</b> con los partidos dispuestos hasta que el veredicto de abajo diga que gobiernas, y después <b>Presentarse a la investidura</b>. Cada socio te pedirá una ley.",
    "Nobody has the {} seats. The bars compare your bloc with your rival's: click <b>Strike a pact</b> with the willing parties until the verdict below says you govern, and then <b>Stand for investiture</b>. Each partner will ask you for a law.",
    "Niemand hat die {} Sitze. Die Balken vergleichen deinen Block mit dem des Rivalen: Klicke bei den bereitwilligen Parteien auf <b>Bündnis schließen</b>, bis das Urteil unten sagt, dass du regierst, und danach auf <b>Zur Wahl stellen</b>. Jeder Partner wird ein Gesetz von dir verlangen.",
    "Personne n'a les {} sièges. Les barres comparent votre bloc à celui du rival : cliquez sur <b>Conclure un accord</b> avec les partis disposés jusqu'à ce que le verdict en bas indique que vous gouvernez, puis sur <b>Se présenter à l'investiture</b>. Chaque partenaire vous demandera une loi.",
    "Ninguém tem as {} cadeiras. As barras comparam seu bloco com o do rival: clique em <b>Pactuar</b> com os partidos dispostos até que o veredito abaixo diga que você governa, e depois em <b>Apresentar-se à investidura</b>. Cada parceiro vai pedir uma lei."],
  ["Quedan {}. Aquí verás las encuestas: da mítines, haz campaña y cuida la unidad del partido (si baja de 25, te quitan el liderazgo). Pasa los meses hasta la noche electoral. Si no ganas a la primera, habrá otras elecciones enseguida.",
    "There are {} left. Here you will see the polls: hold rallies, campaign and look after party unity (if it drops below 25, they take the leadership from you). Pass the months until election night. If you do not win first time, another election will follow soon.",
    "Es bleiben {}. Hier siehst du die Umfragen: Halte Kundgebungen ab, mach Wahlkampf und achte auf die Einheit der Partei (fällt sie unter 25, nimmt man dir den Vorsitz). Lass die Monate bis zur Wahlnacht vergehen. Gewinnst du nicht beim ersten Mal, gibt es bald wieder eine Wahl.",
    "Il reste {}. Vous verrez ici les sondages : tenez des meetings, faites campagne et veillez à l'unité du parti (si elle passe sous 25, on vous retire la direction). Faites passer les mois jusqu'à la soirée électorale. Si vous ne gagnez pas du premier coup, d'autres élections suivront vite.",
    "Faltam {}. Aqui você verá as pesquisas: faça comícios, faça campanha e cuide da unidade do partido (se cair abaixo de 25, tiram sua liderança). Passe os meses até a noite eleitoral. Se não vencer de primeira, haverá outras eleições logo."],
  ["Has ganado: ahora gobiernas. Heredas las leyes que ya estaban en vigor, tus promesas y lo que debas a tus socios. Cambian las pestañas: provincias, economía, gobierno, diplomacia y defensa. Te llevo por todas.",
    "You have won: now you govern. You inherit the laws already in force, your promises and whatever you owe your partners. The tabs change: provinces, economy, government, diplomacy and defence. I will take you through all of them.",
    "Du hast gewonnen: Jetzt regierst du. Du übernimmst die bereits geltenden Gesetze, deine Versprechen und das, was du deinen Partnern schuldest. Die Reiter ändern sich: Provinzen, Wirtschaft, Regierung, Diplomatie und Verteidigung. Ich führe dich durch alle.",
    "Vous avez gagné : maintenant vous gouvernez. Vous héritez des lois déjà en vigueur, de vos promesses et de ce que vous devez à vos partenaires. Les onglets changent : provinces, économie, gouvernement, diplomatie et défense. Je vous les fais tous visiter.",
    "Você venceu: agora governa. Você herda as leis que já estavam em vigor, suas promessas e o que deve aos seus parceiros. As abas mudam: províncias, economia, governo, diplomacia e defesa. Levo você por todas."],
  ["Legislar gobernando es igual que antes, pero ahora las leyes tienen efecto en tu economía y en tus votantes. Si prometiste alguna en campaña o se la debes a un socio, verás el plazo arriba. Pulsa <b>Proponer</b> en una.",
    "Legislating in government works as before, but now laws affect your economy and your voters. If you promised one during the campaign or owe one to a partner, you will see the deadline at the top. Click <b>Propose</b> on one.",
    "Gesetze machen funktioniert an der Regierung wie zuvor, aber jetzt wirken sie auf deine Wirtschaft und deine Wähler. Hast du im Wahlkampf eines versprochen oder schuldest eines einem Partner, siehst du oben die Frist. Klicke bei einem auf <b>Vorschlagen</b>.",
    "Légiférer au gouvernement fonctionne comme avant, mais les lois ont désormais un effet sur votre économie et vos électeurs. Si vous en avez promis une pendant la campagne ou en devez une à un partenaire, vous verrez le délai en haut. Cliquez sur <b>Proposer</b> pour l'une d'elles.",
    "Legislar governando é igual a antes, mas agora as leis afetam sua economia e seus eleitores. Se você prometeu alguma na campanha ou deve uma a um parceiro, verá o prazo no topo. Clique em <b>Propor</b> em uma."],
]);
